  .chip { height: 22px; font-size: 7px; }
  .topbar__right { gap: 6px; }
  .panel--left {
    top: auto;
    bottom: 96px;
    left: 12px;
    width: 176px;
    max-height: 48vh;
    gap: 8px;
  }
  .camera-card .card__head { padding: 7px 10px 6px; }
  .camera-feed { margin: 8px 10px 0; }
  .camera-meta { padding: 6px 10px 8px; }
  .camera-meta span:nth-child(2), .camera-meta span:nth-child(3) { display: none; }
  .control-card { display: none; }
