  .stage-tools { right: 12px; bottom: 96px; }
  .dock {
    bottom: max(10px, env(safe-area-inset-bottom));
    width: calc(100% - 20px);
    padding: 6px;
    gap: 0;
  }
  .dock__divider { margin: 0 2px; }
  .dock-btn { padding: 5px 4px; gap: 5px; }
  .dock-btn__icon { width: 25px; height: 25px; }
  .dock-btn strong { font-size: 6.5px; letter-spacing: 0.05em; }
  .dock-btn > span:last-child small { display: none; }
  .dock-btn:nth-child(6) > span:last-child { display: none; }
