  .privacy-note { display: none; }
  .telemetry-card--perf { display: none; }
  .hero-caption, .stage-tools { bottom: 98px; }
  .dock { bottom: 12px; }
  .toast { bottom: 100px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  .grain { display: none; }
}

import * as THREE from 'three';

function canvas2d(size) {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  return { canvas, ctx: canvas.getContext('2d') };
}

function finish(canvas, { repeat = [1, 1], colorSpace = THREE.SRGBColorSpace } = {}) {
  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeat[0], repeat[1]);
  tex.colorSpace = colorSpace;
  tex.anisotropy = 4;
  tex.needsUpdate = true;
  return tex;
}

/** Classic red web-suit weave, tileable 512px. */
export function createSuitTexture() {
  const S = 512;
  const { canvas, ctx } = canvas2d(S);

  const base = ctx.createLinearGradient(0, 0, S, S);
  base.addColorStop(0, '#c5162e');
  base.addColorStop(0.45, '#a90f25');
  base.addColorStop(1, '#8f0b1e');
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, S, S);

  // Fine athletic weave / noise.
  const img = ctx.getImageData(0, 0, S, S);
  const data = img.data;
  for (let i = 0; i < data.length; i += 4) {
    const n = (Math.random() - 0.5) * 18;
    data[i] = Math.max(0, Math.min(255, data[i] + n));
    data[i + 1] = Math.max(0, Math.min(255, data[i + 1] + n * 0.5));
    data[i + 2] = Math.max(0, Math.min(255, data[i + 2] + n * 0.5));
  }
  ctx.putImageData(img, 0, 0);

  // Subtle vertical fabric streaks.
  ctx.globalAlpha = 0.08;
  for (let x = 0; x < S; x += 3) {
    ctx.fillStyle = x % 6 === 0 ? '#5d0614' : '#e04a5a';
    ctx.fillRect(x, 0, 1, S);
  }
  ctx.globalAlpha = 1;

  const ink = 'rgba(8, 9, 14, 0.92)';
  const inkSoft = 'rgba(8, 9, 14, 0.42)';

  // Web lattice: radial ribs + sagging cross-threads.
  const ribs = 8;
  const ribGap = S / ribs;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // Glow edge under each thread for a raised-screenprint feel.
  ctx.strokeStyle = 'rgba(255, 92, 108, 0.16)';
  ctx.lineWidth = 7;
  for (let i = 0; i < ribs; i++) {
    const x = i * ribGap;
    ctx.beginPath();
    ctx.moveTo(x, -8);
    ctx.bezierCurveTo(x + 7, S * 0.3, x - 7, S * 0.7, x, S + 8);
    ctx.stroke();
  }
  ctx.strokeStyle = inkSoft;
  for (let i = 0; i < ribs; i++) {
    const x = i * ribGap;
    ctx.beginPath();
    ctx.moveTo(x, -8);
    ctx.bezierCurveTo(x + 7, S * 0.3, x - 7, S * 0.7, x, S + 8);
    ctx.stroke();
  }

  const rows = 6;
  const rowGap = S / rows;
  for (let r = 0; r < rows; r++) {
    const y = r * rowGap;
    ctx.strokeStyle = ink;
    ctx.lineWidth = 4.5;
    ctx.beginPath();
    for (let i = 0; i < ribs; i++) {
      const x0 = i * ribGap;
      ctx.moveTo(x0, y);
      ctx.quadraticCurveTo(x0 + ribGap * 0.5, y + rowGap * 0.38, x0 + ribGap, y);
    }
    ctx.stroke();

    // Thin secondary thread.
    ctx.strokeStyle = 'rgba(10, 10, 16, 0.35)';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    for (let i = 0; i < ribs; i++) {
      const x0 = i * ribGap;
      ctx.moveTo(x0, y + 12);
      ctx.quadraticCurveTo(x0 + ribGap * 0.5, y + rowGap * 0.38 + 12, x0 + ribGap, y + 12);
    }
    ctx.stroke();
  }

  // Scattered micro highlights.
  ctx.globalAlpha = 0.15;
  for (let i = 0; i < 160; i++) {
    ctx.fillStyle = '#ff8b97';
    const x = Math.random() * S;
    const y = Math.random() * S;
    ctx.fillRect(x, y, Math.random() * 2 + 0.5, Math.random() * 2 + 0.5);
  }
  ctx.globalAlpha = 1;

  return finish(canvas, { repeat: [2, 2] });
}

/** Deep navy compression fabric with a faint carbon weave. */
export function createBlueSuitTexture() {
  const S = 512;
  const { canvas, ctx } = canvas2d(S);

  const base = ctx.createLinearGradient(0, 0, S, S);
  base.addColorStop(0, '#123b75');
  base.addColorStop(0.5, '#0b2a58');
  base.addColorStop(1, '#071c3d');
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, S, S);

  const img = ctx.getImageData(0, 0, S, S);
  const data = img.data;
  for (let i = 0; i < data.length; i += 4) {
    const n = (Math.random() - 0.5) * 14;
    data[i] += n * 0.5;
    data[i + 1] += n;
    data[i + 2] += n * 1.4;
  }
  ctx.putImageData(img, 0, 0);

  ctx.strokeStyle = 'rgba(112, 178, 255, 0.09)';
  ctx.lineWidth = 1;
  for (let i = -S; i < S * 2; i += 9) {
    ctx.beginPath();
    ctx.moveTo(i, 0);
    ctx.lineTo(i + S, S);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(i, S);
    ctx.lineTo(i + S, 0);
    ctx.stroke();
  }

  // Panel seams.
  ctx.strokeStyle = 'rgba(3, 9, 20, 0.85)';
  ctx.lineWidth = 5;
  for (let x = 0; x <= S; x += 128) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, S);
    ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(111, 183, 255, 0.14)';
  ctx.lineWidth = 1.4;
  for (let x = 0; x <= S; x += 128) {
    ctx.beginPath();
    ctx.moveTo(x + 4, 0);
    ctx.lineTo(x + 4, S);
    ctx.stroke();
  }

  return finish(canvas, { repeat: [2, 1] });
}

/** Black spider emblem with transparent background. */
export function createEmblemTexture({ color = '#07090e', elongate = 1 } = {}) {
  const S = 512;
  const { canvas, ctx } = canvas2d(S);
  ctx.clearRect(0, 0, S, S);
  ctx.translate(S / 2, S / 2);
  ctx.scale(1, elongate);
  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // Legs — four per side, articulated.
  ctx.lineWidth = 17;
  const legs = [
    [[-18, -84], [-78, -150], [-152, -168], [-190, -132]],
    [[-24, -66], [-112, -104], [-178, -96], [-202, -50]],
    [[-26, -38], [-114, -18], [-186, 22], [-200, 72]],
    [[-18, -14], [-82, 38], [-128, 100], [-148, 160]],
  ];
  for (const side of [1, -1]) {
    for (const leg of legs) {
      const [a, b, c, d] = leg;
      ctx.beginPath();
      ctx.moveTo(a[0] * side, a[1]);
      ctx.quadraticCurveTo(b[0] * side, b[1], c[0] * side, c[1]);
      ctx.quadraticCurveTo((c[0] * 0.6 + d[0] * 0.4) * side, (c[1] * 0.6 + d[1] * 0.4), d[0] * side, d[1]);
      ctx.stroke();
    }
  }

  // Body.
  ctx.beginPath();
  ctx.ellipse(0, 52, 27, 50, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(0, -8, 25, 32, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(0, -48, 16, 20, 0, 0, Math.PI * 2);
  ctx.fill();

  // Abdomen highlight cut.
  ctx.globalCompositeOperation = 'destination-out';
  ctx.beginPath();
  ctx.ellipse(0, 54, 2.5, 26, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalCompositeOperation = 'source-over';

  return finish(canvas, { repeat: [1, 1] });
}

/** Soft radial contact shadow used under the feet. */
export function createShadowTexture() {
  const S = 512;
  const { canvas, ctx } = canvas2d(S);
  const g = ctx.createRadialGradient(S / 2, S / 2, 8, S / 2, S / 2, S / 2);
  g.addColorStop(0, 'rgba(0, 0, 0, 0.72)');
  g.addColorStop(0.4, 'rgba(0, 0, 0, 0.36)');
  g.addColorStop(1, 'rgba(0, 0, 0, 0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, S, S);
  return finish(canvas, { repeat: [1, 1] });
}

/** Radial red floor glow. */
export function createGlowTexture(color = '#e11d38') {
  const S = 512;
  const { canvas, ctx } = canvas2d(S);
  const g = ctx.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2);
  g.addColorStop(0, color);
  g.addColorStop(0.28, color);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.globalAlpha = 0.55;
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, S, S);
  return finish(canvas, { repeat: [1, 1] });
}

/** Skin pore / warmth map for Peter's face. */
export function createSkinTexture() {
  const S = 512;
  const { canvas, ctx } = canvas2d(S);
  ctx.fillStyle = '#c98f6f';
  ctx.fillRect(0, 0, S, S);

  const img = ctx.getImageData(0, 0, S, S);
  const data = img.data;
  for (let i = 0; i < data.length; i += 4) {
    const n = (Math.random() - 0.5) * 12;
    data[i] += n * 1.1;
    data[i + 1] += n;
    data[i + 2] += n * 0.75;
  }
  ctx.putImageData(img, 0, 0);

  ctx.globalAlpha = 0.12;
  for (let i = 0; i < 240; i++) {
    ctx.fillStyle = Math.random() > 0.5 ? '#9a5d47' : '#e5b190';
    const x = Math.random() * S;
    const y = Math.random() * S;
    ctx.fillRect(x, y, 1.5, 1.5);
  }
  ctx.globalAlpha = 1;
  return finish(canvas, { repeat: [1, 1] });
}

/** Swept dark-brown hair strands. */
export function createHairTexture() {
  const S = 512;
  const { canvas, ctx } = canvas2d(S);
  ctx.fillStyle = '#2a1a13';
  ctx.fillRect(0, 0, S, S);
  ctx.lineWidth = 2;
  for (let i = 0; i < 900; i++) {
    const x = Math.random() * S;
    const y = Math.random() * S;
    ctx.strokeStyle = Math.random() > 0.55 ? 'rgba(96, 63, 43, 0.35)' : 'rgba(10, 6, 4, 0.4)';
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.quadraticCurveTo(x + 8, y + 20, x + 2, y + 48);
    ctx.stroke();
  }
  return finish(canvas, { repeat: [2, 2] });
}

import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import {
  createSuitTexture,
  createBlueSuitTexture,
  createEmblemTexture,
  createSkinTexture,
  createHairTexture,
} from './textures.js';

const UP = new THREE.Vector3(0, 1, 0);
const DOWN = new THREE.Vector3(0, -1, 0);
const FORWARD = new THREE.Vector3(0, 0, 1);

const _v1 = new THREE.Vector3();
const _v2 = new THREE.Vector3();
const _v3 = new THREE.Vector3();
const _x = new THREE.Vector3();
const _y = new THREE.Vector3();
const _z = new THREE.Vector3();
const _m = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const _qInv = new THREE.Quaternion();
const _e = new THREE.Euler();

function basisQuat(xHint, yDir, out) {
  _y.copy(yDir);
  if (_y.lengthSq() < 1e-8) _y.copy(UP);
  _y.normalize();
  _x.copy(xHint);
  _x.addScaledVector(_y, -_x.dot(_y));
  if (_x.lengthSq() < 1e-8) {
    _x.set(1, 0, 0);
    _x.addScaledVector(_y, -_x.dot(_y));
    if (_x.lengthSq() < 1e-8) _x.set(0, 0, 1).addScaledVector(_y, -_y.z);
  }
  _x.normalize();
  _z.crossVectors(_x, _y).normalize();
  _x.crossVectors(_y, _z).normalize();
  _m.makeBasis(_x, _y, _z);
  return out.setFromRotationMatrix(_m);
}

function forwardQuat(yDir, forwardHint, out) {
  _y.copy(yDir);
  if (_y.lengthSq() < 1e-8) _y.copy(DOWN);
  _y.normalize();
  _z.copy(forwardHint);
  _z.addScaledVector(_y, -_z.dot(_y));
  if (_z.lengthSq() < 1e-8) {
    _z.copy(FORWARD);
    _z.addScaledVector(_y, -_z.dot(_y));
    if (_z.lengthSq() < 1e-8) _z.set(0, 0, 1);
  }
  _z.normalize();
  _x.crossVectors(_y, _z).normalize();
  _z.crossVectors(_x, _y).normalize();
  _m.makeBasis(_x, _y, _z);
  return out.setFromRotationMatrix(_m);
}

function capsule(radius, length, material, radialSegments = 12) {
  const geo = new THREE.CapsuleGeometry(radius, Math.max(length - radius * 2, 0.01), 4, radialSegments);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.y = length / 2;
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function lathe(profile, segments = 18) {
  return new THREE.LatheGeometry(
    profile.map(([r, y]) => new THREE.Vector2(r, y)),
    segments,
  );
}

function makeJoint(parent, name, x, y, z) {
  const g = new THREE.Group();
  g.name = name;
  g.position.set(x, y, z);
  parent.add(g);
  return g;
}

export class SpiderCharacter {
  constructor() {
    this.group = new THREE.Group();
    this.group.name = 'SpiderCharacter';
    this.root = new THREE.Group();
    this.root.name = 'CharacterRoot';
    this.group.add(this.root);

    this.maskGroup = new THREE.Group();
    this.faceGroup = new THREE.Group();
    this.faceGroup.visible = false;
    this.masked = true;

    this.bones = {};
    this.smoothQuats = new Map();
    this.smoothRoot = new THREE.Vector3(0, 0.92, 0);
    this.smoothFace = {
      yaw: 0, pitch: 0, roll: 0, jaw: 0, smile: 0, brow: 0,
      blinkL: 0, blinkR: 0, squint: 0,
    };
    this.faceSmoothed = { ...this.smoothFace };
    this.groundOffset = 0;
    this.idleT = 0;
    this.ready = false;

    this._makeMaterials();
    this._buildRig();
    this._buildSuit();
    this._buildMaskedHead();
    this._buildFace();
    this._buildSkeletonOverlay();
    this.setMasked(true);
  }

  _makeMaterials() {
    const suitTex = createSuitTexture();
