  const now = performance.now();
  if (now - this.fpsTime >= 500) {
    const measured = (this.frameCount * 1000) / (now - this.fpsTime);
    this.fps += (measured - this.fps) * 0.5;
    this.frameCount = 0;
    this.fpsTime = now;
    this._adaptQuality(measured);
  }
}

_adaptQuality(measured) {
  if (this.quality !== 'auto' || !this.targetDpr) return;
  const now = performance.now();
  if (this.adaptiveCooldown > now) return;
  if (measured < 44) {
    this.lowFpsTime += 500;
    this.highFpsTime = 0;
    if (this.lowFpsTime > 1600 && this.targetDpr > 1.02) {
      this.targetDpr = Math.max(1, this.targetDpr - 0.22);
      this.renderer.setPixelRatio(this.targetDpr);
      this.resize();
      this.lowFpsTime = 0;
      this.adaptiveCooldown = now + 2500;
    }
  } else if (measured > 57) {
    this.highFpsTime += 500;
    this.lowFpsTime = 0;
    if (this.highFpsTime > 5000 && this.targetDpr < Math.min(window.devicePixelRatio || 1, 1.6)) {
      this.targetDpr = Math.min(Math.min(window.devicePixelRatio || 1, 1.6), this.targetDpr + 0.12);
      this.renderer.setPixelRatio(this.targetDpr);
      this.resize();
      this.highFpsTime = 0;
      this.adaptiveCooldown = now + 3000;
    }
  } else {
    this.lowFpsTime = 0;
    this.highFpsTime = 0;
  }
}

